,p_plug_name=>'DASHBOARD'
,p_static_id=>'dashboard'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(22774456928165944644)
