,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''Total Riders'' AS card_title, COUNT(*) AS card_value FROM RIDER WHERE status = ''ACTIVE''',
'UNION ALL',
'SELECT ''Active Loans'', COUNT(*) FROM LOAN_AGREEMENT WHERE status = ''ACTIVE''',
'UNION ALL',
